// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    EmergencyOracleFactory c;
    function setUp() public { c = new EmergencyOracleFactory(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        vm.prank(attacker);

        bool success;
        try c.newEmergencyOracle("test") {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(!success, "Non-owner should not be able to create emergency oracle");
    }
}
